# ---------------- writer + assertions ----------------
import json as _j
batches = _j.loads(pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round66/batches.json").read_text())
ids = batches["B16"] + batches["B17"] + batches["B18"]
assert len(ids) == 60 and set(ids) == set(DATA.keys()), (len(ids), set(ids) ^ set(DATA.keys()))
total = 0
for cid in ids:
    d = DATA[cid]
    obj = {"case_id": cid, "prediction_text": d["pred"], "basis": d["basis"], "confidence": d["conf"],
           "trigger": d["trig"]}
    assert set(obj.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    assert 0.0 <= obj["confidence"] <= 1.0
    assert set(obj["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    assert all(isinstance(obj["trigger"][k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    p = OUT / f"{cid}.json"
    p.write_text(_j.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    total += p.stat().st_size
cm = sum(1 for c in ids if DATA[c]["trig"]["changed_main"])
ru = sum(1 for c in ids if DATA[c]["trig"]["reserve_used"])
di = sum(1 for c in ids if DATA[c]["trig"]["disputed"])
print(f"WROTE {len(ids)} files total_bytes={total} changed_main={cm} reserve_used={ru} disputed={di}")
